raw:
{
  "spells": [
    {
      "id": "spell_water_01",
      "theory": "凝露术不创造水，只将周围空气中已存在的水汽引向目标表面。施法者以魔力在杯壁外侧织出极细的冷纹，使水汽在纹路交汇处凝结成珠。凝结速度完全取决于空气湿度：干燥天气里可能仅得薄雾，潮湿河畔则能较快聚成可饮的少量水。整个过程持续至多30分钟，之后冷纹自行消散，已凝出的水留在杯壁。",
      "casting": "用食指与中指并拢，沿杯壁外缘画一道螺旋向下的纹路，同时从指腹持续送出微量魔力。画完最后一圈时轻叩杯底一次，表示冷纹闭合。",
      "failure": "若螺旋画得过快，冷纹会断裂成数段，水珠只出现在零散几点，且很快重新蒸发。若魔力送入过多，杯壁可能结出薄霜而非可饮水，霜层融化后混入灰尘，无法直接饮用。失败时施法者会感到指尖发凉，但不会受伤。",
      "counters": [
        "用干布反复擦拭杯壁，破坏尚未闭合的冷纹，凝结便会停止。"
      ],
      "socialConsequences": "河谷乡民在长途跋涉时常用它补充饮水，但不会将其视为可靠水源，仍会寻找活水。陶匠和杯商乐见其成，因为人们更愿意购买表面略有粗糙的杯子。若在他人井边施放，井主可能要求施法者先说明来意，以免被误认为在窃取井水。旅店老板通常允许住客在房内使用，但要求不得让冷凝水浸湿床铺。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时冷纹常断，凝结水珠稀少且分布不均。",
        "稳定画完螺旋后，潮湿空气中可较快聚出少量可饮水。",
        "熟练者能控制冷纹密度，使水珠集中落在杯底而不外溢。",
        "更高熟练度下冷纹极少断裂，但凝水速度仍受空气湿度限制。"
      ]
    },
    {
      "id": "spell_water_02",
      "theory": "净水术以魔力推动水中的悬浮颗粒相互碰撞并聚成较大絮团，絮团因重量增加而沉向容器底部。它只能处理物理性污物，如泥沙、草屑和部分虫卵，无法分解溶于水的毒素或盐分。施法者需将魔力均匀铺满整桶水的截面，持续30分钟，使絮团充分沉降。之后清水位于上层，沉淀物留在桶底。",
      "casting": "双掌张开，掌心朝向桶口，从桶沿开始缓慢向下压送魔力，同时以拇指在掌心画圈表示絮团汇聚。当水面出现第一缕浑浊下沉时，保持双掌姿势不动。",
      "failure": "魔力分布不均时，只有局部水变清，其余部分依旧浑浊。若中途停止压送，已聚成的絮团会重新散开，整桶水回到原状。失败不会使水变得有毒，但可能搅起底部沉淀，让原本较清的水变浑。",
      "counters": [
        "用长勺快速搅动整桶水，打散正在下沉的絮团，净水过程即被中断。"
      ],
      "socialConsequences": "河谷村落常请掌握此术的人在雨季为公共水缸净水，报酬多为粮食或布匹。城市中产家庭愿意付费请人处理储水，但不会用它替代煮沸。港口船主担心船员依赖此术而忽略淡水补给，因此仍要求按航程装载足量清水。若在他人水井中施放，井主通常要求先取得同意，以免沉淀物堵塞井底。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时魔力覆盖不全，桶中只有部分水变清。",
        "掌握均匀铺送后，一桶水的悬浮污物能较好沉降。",
        "熟练者可控制絮团大小，使沉淀更快且不易重新浮起。",
        "更高熟练度下净水效果稳定，但仍不能消除溶解的毒素。"
      ]
    },
    {
      "id": "spell_water_03",
      "theory": "辨泉术将微量魔力送入水体，再读取返回的细微波动，从而判断水源的盐分高低与腐败气味。它不探测暗藏契约、魔法陷阱或生物意图，只反映水中可感知的化学与生物迹象。施法者需将魔力沿水面铺开，持续30分钟，期间可缓慢移动手部以覆盖不同位置。超过30分钟后波动会变得杂乱，判断不再可靠。",
      "casting": "单手掌心向下悬于水面一掌高处，五指微微张开，缓慢画圈三次。随后将掌心贴近水面但不接触，闭眼感受返回的波动变化。",
      "failure": "若画圈过快，返回波动会混成一片，施法者只能得到模糊的咸或臭的印象，无法区分盐分与腐败。若掌心接触水面，魔力会散入水中，导致接下来片刻内无法再次施术。失败不会污染水源，但可能让施法者误判水质。",
      "counters": [
        "在水面撒一把细沙，沙粒扰动返回波动，辨泉结果随即混乱。"
      ],
      "socialConsequences": "河谷牧民在迁徙前会请人辨泉，以避开咸苦或腐坏的水塘。城市药剂师和酿酒匠偶尔用它检查原料用水，但更信任尝味与试纸。港口检疫官可能要求船员在卸货前辨明压舱水是否腐败，以免污染港池。若在他人水井边施放，井主可能要求施法者说明结果，避免谣言影响井水买卖。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时波动杂乱，只能大致分辨极咸与极臭的水。",
        "稳定画圈后，可较清楚区分盐分高低与腐败气味。",
        "熟练者能移动手掌比较不同位置，判断局部水质差异。",
        "更高熟练度下判断更可靠，但仍无法探测暗藏契约或毒素。"
      ]
    }
  ]
}
